<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';$user=require_api_user();$studentId=(string)($_GET['student_id']??'');if(!$studentId||!can_access_student($user,$studentId))json_response(false,'Akses data siswa ditolak.',null,403);$pdo=db();$stmt=$pdo->prepare('SELECT nama_lengkap,nis,kelas FROM students WHERE id=?');$stmt->execute([$studentId]);$student=$stmt->fetch();if(!$student)json_response(false,'Siswa tidak ditemukan.',null,404);$stmt=$pdo->prepare('SELECT * FROM daily_student_reports WHERE student_id=? ORDER BY tanggal DESC');$stmt->execute([$studentId]);$rows=$stmt->fetchAll();$filename='laporan-'.preg_replace('/[^a-z0-9]+/','-',strtolower($student['nama_lengkap'])).'.xls';header('Content-Type: application/vnd.ms-excel; charset=utf-8');header('Content-Disposition: attachment; filename="'.$filename.'"');echo "\xEF\xBB\xBF";?><table border="1"><tr><th colspan="6">NGAJIYUK - LAPORAN HARIAN</th></tr><tr><td>Nama</td><td colspan="2"><?= e($student['nama_lengkap']) ?></td><td>NIS</td><td colspan="2"><?= e($student['nis']) ?></td></tr><tr><th>Tanggal</th><th>Presensi</th><th>Kegiatan</th><th>Tadarus</th><th>Hafalan</th><th>Catatan Guru</th></tr><?php foreach($rows as $row):?><tr><td><?= e($row['tanggal']) ?></td><td><?= e($row['status_presensi']) ?></td><td><?= e($row['kegiatan']) ?></td><td><?= e($row['ringkasan_tadarus']) ?></td><td><?= e($row['ringkasan_hafalan']) ?></td><td><?= e($row['catatan_guru']) ?></td></tr><?php endforeach;?></table>

